using System.Text.RegularExpressions;
using System.Xml.Linq;
using Xunit;

namespace BARANG.Backoffice.Tests;

public sealed class CustomerManagementUiTests
{
    private static readonly string Root=FindRoot();private static readonly string Page=Read("Components","Pages","CustomerManager.razor");private static readonly string Editor=Read("Components","CustomerEditor.razor");private static readonly string Children=Read("Components","CustomerChildWorkspace.razor");
    [Fact]public void CustomersNavigationOpensAnInteractiveServerPagedGrid(){Assert.Contains("@page \"/manage/customers\"",Page);Assert.Contains("@rendermode InteractiveServer",Page);Assert.Contains("pageNumber={Page}",Page);Assert.Contains("pageSize={PageSize}",Page);Assert.Contains("sortBy={SortBy}",Page);Assert.Contains("customerType={TypeFilter}",Page);Assert.Contains("status={StatusFilter}",Page);Assert.Contains("BarangLoadingState",Page);Assert.Contains("NoCustomers",Page);Assert.DoesNotContain("<BarangIcon Name=\"search\"",Page);}
    [Fact]public void EditorExposesIdentityAndAllRealChildWorkspaces(){foreach(string tab in new[]{"General","Addresses","Contacts","FinancialCommercial","BankAccounts"})Assert.Contains($"C[\"{tab}\"]",Editor);Assert.Contains("Type==\"Individual\"",Editor);Assert.Contains("LegalName",Editor);Assert.Contains("TypeLocked",Editor);Assert.True(Regex.Matches(Editor,"<LocaleDateInput").Count>=2);Assert.True(Regex.Matches(Editor,"<ReferenceSelect").Count>=7);Assert.Contains("<SearchableSelect",Editor);Assert.Contains("<ReferenceSelect",Children);Assert.Contains("Reference:\"bank\"",Children);Assert.Contains("Reference:\"contact.role\"",Children);}
    [Fact]public void EveryChildActionIsWiredToAPersistentApiOperation(){Assert.Contains("/financial",Editor);Assert.Contains("/status",Page);Assert.Contains("status=Id is not null&&CanStatus?Status:null",Editor);foreach(string kind in new[]{"addresses","contacts","bank-accounts"})Assert.Contains(kind,Children);Assert.Contains("HttpMethod.Delete",Children);Assert.Contains("isPrimary",Children);Assert.Contains("isDefault",Children);Assert.Contains("SetDefault(",Children);Assert.Contains("Type==\"LegalEntity\"",Editor);Assert.Contains("CloseRequested",Children);Assert.DoesNotContain("raw JSON",Editor,StringComparison.OrdinalIgnoreCase);}
    [Fact]public void CustomerResourcesAreCompleteUniqueAndThreeLanguage(){string folder=Path.Combine(Root,"01_CORE","src","BARANG.Backoffice","Localization");string[] files=Directory.GetFiles(folder,"CustomerStrings*.resx");Assert.Equal(3,files.Length);string[] expected=Keys(files[0]);Assert.All(files,file=>Assert.Equal(expected,Keys(file)));Assert.All(files,file=>Assert.Equal(Keys(file).Length,Keys(file).Distinct().Count()));}
    [Fact]public void FinancialAndCompanySecurityAreExplicitInTheUiContract(){Assert.Contains("customer.financial.read",Editor);Assert.Contains("customer.financial.manage",Editor);Assert.Contains("AuthClaimTypes.CompanyId",Editor);Assert.Contains("X-Company",Read("Api","CoreApiClient.cs"),StringComparison.OrdinalIgnoreCase);}
    private static string[]Keys(string file)=>XDocument.Load(file).Root!.Elements("data").Select(x=>(string)x.Attribute("name")!).OrderBy(x=>x,StringComparer.Ordinal).ToArray();private static string Read(params string[]parts)=>File.ReadAllText(Path.Combine([Root,"01_CORE","src","BARANG.Backoffice",..parts]));private static string FindRoot(){DirectoryInfo? d=new(AppContext.BaseDirectory);while(d is not null&&!Directory.Exists(Path.Combine(d.FullName,"01_CORE")))d=d.Parent;return d?.FullName??throw new DirectoryNotFoundException();}
}
